import{_ as o,r as p,o as c,c as l,e as i,a as s,b as a,d as t}from"./app-6c9584fa.js";const u={},r={href:"https://docs.claude.com/en/docs/build-with-claude/tool-use",target:"_blank",rel:"noopener noreferrer"},d={href:"https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/AsyncGenerator",target:"_blank",rel:"noopener noreferrer"};function k(m,n){const e=p("ExternalLinkIcon");return c(),l("div",null,[n[8]||(n[8]=i(`<h1 id="第二章-我是如何剖析-claude-code-queryengine-与大模型交互机制的" tabindex="-1"><a class="header-anchor" href="#第二章-我是如何剖析-claude-code-queryengine-与大模型交互机制的" aria-hidden="true">#</a> 第二章：我是如何剖析 Claude Code QueryEngine 与大模型交互机制的</h1><p>大家好。今天，我们将继续探索 Claude Code 的核心源码。如果说上一章讲的架构是它的骨架，那么今天我们要聊的 <strong>QueryEngine（查询引擎）</strong>，绝对是它的大脑神经中枢。</p><p>作为一款 AI 编程助手，Claude Code 是怎么和远在天边的 Claude 3.5 模型对话的？当模型要求执行一个复杂的 Bash 命令时，本地又是怎么安全、实时地跑起来的？</p><p>学习完这章后，你会对以下内容有清晰的认识：</p><ol><li><strong>QueryEngine 的核心使命</strong>：它是怎么管理长达几个小时的上下文的？</li><li><strong>大循环（The Query Loop）</strong>：揭秘 <code>while(true)</code> 里的惊天秘密。</li><li><strong>上下文瘦身术（Context Compaction）</strong>：5 道防线，教你如何优雅地压缩上下文，既省钱又不丢关键信息。</li><li><strong>工具流式执行（Streaming Tool Execution）</strong>：模型还没回答完，工具就已经跑起来了？</li><li><strong>动手实践</strong>：给大循环加一个自定义的拦截器。</li></ol><hr><h2 id="一、宏观视角-什么是-queryengine" tabindex="-1"><a class="header-anchor" href="#一、宏观视角-什么是-queryengine" aria-hidden="true">#</a> 一、宏观视角：什么是 QueryEngine？</h2><p>翻开 <code>src/query.ts</code> 源码，你会发现它的核心就是暴露了一个 <code>query()</code> 函数。它是一个极其复杂的<strong>异步生成器（AsyncGenerator）</strong>。</p><p>你可以把 QueryEngine 想象成一个“同声传译+执行官”。</p><ul><li>接收我们的输入（比如：“帮我写个 Python 脚本”）。</li><li>把本地的代码、文件树、以及历史聊天记录打包好，通过 <code>callModel</code> 发给 Claude 大模型。</li><li><strong>流式（Streaming）</strong> 接收大模型的回复，一点点吐给终端 UI。</li><li>如果大模型在回复里夹带了“工具调用（Tool Use）”的指令，它能<strong>实时拦截并执行</strong>这些本地命令。</li><li>把执行结果再喂回给大模型，直到大模型说“任务完成”。</li></ul><p>这一切，都被封装在一个巨大的 <code>while(true)</code> 循环中，也就是源码里的 <code>queryLoop</code> 函数。</p><hr><h2 id="二、精妙绝伦-上下文瘦身术-context-compaction" tabindex="-1"><a class="header-anchor" href="#二、精妙绝伦-上下文瘦身术-context-compaction" aria-hidden="true">#</a> 二、精妙绝伦：上下文瘦身术（Context Compaction）</h2><p>在使用大模型时，最大的痛点就是：<strong>上下文太长了！</strong> Token 超限不仅会导致 API 报错（Prompt Too Long），而且非常费钱。我在看 <code>query.ts</code> 时，被它处理上下文的精细程度震惊到了。</p><p>在每次发请求给模型前，它会依次经过 <strong>5 道防线</strong> 来对上下文进行瘦身：</p><ol><li><strong>预算控制 (<code>applyToolResultBudget</code>)</strong>： <ul><li>比如你跑了一个 <code>cat package-lock.json</code>，结果返回了几万行。这里会强制给工具结果设定一个 Token 预算，超出的部分直接被截断或总结。</li></ul></li><li><strong>历史裁剪 (<code>snipCompactIfNeeded</code>)</strong>： <ul><li>如果开启了 <code>HISTORY_SNIP</code>，它会智能地裁掉历史对话中一些毫无营养的闲聊，释放 Token。</li></ul></li><li><strong>微型压缩 (<code>microcompact</code>)</strong>： <ul><li>这是对特定工具结果的压缩。比如你修改了一个文件，它可能只保留 Diff 差异，而不是把整个新旧文件都塞在上下文里。</li></ul></li><li><strong>上下文折叠 (<code>contextCollapse.applyCollapsesIfNeeded</code>)</strong>： <ul><li>将一些已经完结的中间步骤“折叠”起来，只保留最终结论。</li></ul></li><li><strong>自动总结 (<code>autocompact</code>)</strong>： <ul><li>终极大招。如果经过前面几步，Token 还是接近上限，它会触发 <code>autocompact</code>（背后其实是偷偷起了一个子代理），让模型自己把之前的长篇大论总结成一段精简的摘要，替换掉原来的几十条消息。</li></ul></li></ol><p>这段逻辑就像一个过滤漏斗，我在源码里给大家提炼出了骨架：</p><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token comment">// 摘自 src/query.ts 的 queryLoop 函数</span>
<span class="token keyword">let</span> messagesForQuery <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token operator">...</span>messages<span class="token punctuation">]</span>

<span class="token comment">// 1. 限制工具输出大小</span>
messagesForQuery <span class="token operator">=</span> <span class="token keyword">await</span> <span class="token function">applyToolResultBudget</span><span class="token punctuation">(</span>messagesForQuery<span class="token punctuation">,</span> <span class="token operator">...</span><span class="token punctuation">)</span>

<span class="token comment">// 2. 裁剪历史</span>
<span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token function">feature</span><span class="token punctuation">(</span><span class="token string">&#39;HISTORY_SNIP&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">const</span> snipResult <span class="token operator">=</span> snipModule<span class="token punctuation">.</span><span class="token function">snipCompactIfNeeded</span><span class="token punctuation">(</span>messagesForQuery<span class="token punctuation">)</span>
  messagesForQuery <span class="token operator">=</span> snipResult<span class="token punctuation">.</span>messages
<span class="token punctuation">}</span>

<span class="token comment">// 3. 微型压缩</span>
<span class="token keyword">const</span> microcompactResult <span class="token operator">=</span> <span class="token keyword">await</span> deps<span class="token punctuation">.</span><span class="token function">microcompact</span><span class="token punctuation">(</span>messagesForQuery<span class="token punctuation">,</span> <span class="token operator">...</span><span class="token punctuation">)</span>
messagesForQuery <span class="token operator">=</span> microcompactResult<span class="token punctuation">.</span>messages

<span class="token comment">// 4. 上下文折叠</span>
<span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token function">feature</span><span class="token punctuation">(</span><span class="token string">&#39;CONTEXT_COLLAPSE&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">const</span> collapseResult <span class="token operator">=</span> <span class="token keyword">await</span> contextCollapse<span class="token punctuation">.</span><span class="token function">applyCollapsesIfNeeded</span><span class="token punctuation">(</span>messagesForQuery<span class="token punctuation">,</span> <span class="token operator">...</span><span class="token punctuation">)</span>
  messagesForQuery <span class="token operator">=</span> collapseResult<span class="token punctuation">.</span>messages
<span class="token punctuation">}</span>

<span class="token comment">// 5. 自动总结 (终极杀器)</span>
<span class="token keyword">const</span> <span class="token punctuation">{</span> compactionResult <span class="token punctuation">}</span> <span class="token operator">=</span> <span class="token keyword">await</span> deps<span class="token punctuation">.</span><span class="token function">autocompact</span><span class="token punctuation">(</span>messagesForQuery<span class="token punctuation">,</span> <span class="token operator">...</span><span class="token punctuation">)</span>
<span class="token keyword">if</span> <span class="token punctuation">(</span>compactionResult<span class="token punctuation">)</span> <span class="token punctuation">{</span>
  messagesForQuery <span class="token operator">=</span> <span class="token function">buildPostCompactMessages</span><span class="token punctuation">(</span>compactionResult<span class="token punctuation">)</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="三、庖丁解牛-大循环与流式工具执行" tabindex="-1"><a class="header-anchor" href="#三、庖丁解牛-大循环与流式工具执行" aria-hidden="true">#</a> 三、庖丁解牛：大循环与流式工具执行</h2><p>上下文准备好了，接下来就是发请求给模型。这里有两大亮点：<strong>无限循环</strong>和<strong>边看边做（Streaming Tool Execution）</strong>。</p><h3 id="_1-the-query-loop-无限循环-与它的-刹车机制" tabindex="-1"><a class="header-anchor" href="#_1-the-query-loop-无限循环-与它的-刹车机制" aria-hidden="true">#</a> 1. The Query Loop (无限循环) 与它的“刹车机制”</h3><p><code>queryLoop</code> 为什么是一个 <code>while(true)</code> 循环？ 因为很多编程任务不是一回合就能搞定的。比如你让它“修复这个 Bug”，它可能需要：</p><ul><li>回合 1：调用 <code>grep</code> 搜索报错信息。（大模型返回 Tool Use，本地执行，进入下一循环）</li><li>回合 2：调用 <code>cat</code> 查看具体文件。（大模型返回 Tool Use，本地执行，进入下一循环）</li><li>回合 3：调用 <code>edit</code> 修改文件。（大模型返回 Tool Use，本地执行，进入下一循环）</li></ul><p><strong>那么，这个 <code>while(true)</code> 到底是怎么停下来的呢？难道会一直死循环吗？</strong></p><p>当然不会。我在源码中找到了它的几种“刹车机制”：</p><p><strong>机制一：自然完结（最常见）</strong> 当大模型认为任务已经完成，它在回复中**不再包含任何工具调用（Tool Use）**时，源码中一个叫做 <code>needsFollowUp</code> 的标记就会保持为 <code>false</code>。循环走到一半就会直接 <code>return</code> 跳出：</p><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token comment">// 摘自 src/query.ts</span>
<span class="token keyword">let</span> needsFollowUp <span class="token operator">=</span> <span class="token boolean">false</span><span class="token punctuation">;</span>

<span class="token keyword">for</span> <span class="token keyword">await</span> <span class="token punctuation">(</span><span class="token keyword">const</span> message <span class="token keyword">of</span> deps<span class="token punctuation">.</span><span class="token function">callModel</span><span class="token punctuation">(</span><span class="token punctuation">{</span><span class="token operator">...</span><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token comment">// ... 如果模型返回了工具调用，就会把 needsFollowUp 设置为 true</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span>message<span class="token punctuation">.</span>type <span class="token operator">===</span> <span class="token string">&#39;tool_use_block&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    needsFollowUp <span class="token operator">=</span> <span class="token boolean">true</span><span class="token punctuation">;</span>
  <span class="token punctuation">}</span>
<span class="token punctuation">}</span>

<span class="token comment">// 🎯 核心刹车点：如果模型没有调用工具，说明它回答完了</span>
<span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>needsFollowUp<span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token comment">// ... 忽略一些错误恢复逻辑</span>
  <span class="token keyword">return</span> <span class="token punctuation">{</span> reason<span class="token operator">:</span> <span class="token string">&#39;completed&#39;</span> <span class="token punctuation">}</span><span class="token punctuation">;</span> <span class="token comment">// 成功跳出死循环！</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>机制二：最大回合数限制（防失控）</strong> 如果遇到一个很难的 Bug，模型一直在疯狂试错调用工具怎么办？源码在每次循环的末尾加了强制熔断机制：</p><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token comment">// 摘自 src/query.ts 循环末尾</span>
<span class="token keyword">const</span> nextTurnCount <span class="token operator">=</span> turnCount <span class="token operator">+</span> <span class="token number">1</span><span class="token punctuation">;</span>

<span class="token comment">// 检查是否达到了最大回合数限制</span>
<span class="token keyword">if</span> <span class="token punctuation">(</span>maxTurns <span class="token operator">&amp;&amp;</span> nextTurnCount <span class="token operator">&gt;</span> maxTurns<span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">yield</span> <span class="token function">createAttachmentMessage</span><span class="token punctuation">(</span><span class="token punctuation">{</span>
    type<span class="token operator">:</span> <span class="token string">&#39;max_turns_reached&#39;</span><span class="token punctuation">,</span>
    maxTurns<span class="token punctuation">,</span>
    turnCount<span class="token operator">:</span> nextTurnCount<span class="token punctuation">,</span>
  <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">return</span> <span class="token punctuation">{</span> reason<span class="token operator">:</span> <span class="token string">&#39;max_turns&#39;</span><span class="token punctuation">,</span> turnCount<span class="token operator">:</span> nextTurnCount <span class="token punctuation">}</span><span class="token punctuation">;</span> <span class="token comment">// 强制停车！</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>机制三：用户手动打断（Ctrl+C）</strong> 当你在终端按下 <code>Ctrl+C</code> 时，会触发 AbortController 信号，循环也会立刻安全退出：</p><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token comment">// 摘自 src/query.ts 的工具执行阶段</span>
<span class="token keyword">if</span> <span class="token punctuation">(</span>toolUseContext<span class="token punctuation">.</span>abortController<span class="token punctuation">.</span>signal<span class="token punctuation">.</span>aborted<span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">return</span> <span class="token punctuation">{</span> reason<span class="token operator">:</span> <span class="token string">&#39;aborted_tools&#39;</span> <span class="token punctuation">}</span><span class="token punctuation">;</span> <span class="token comment">// 用户喊停，立刻退出</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>正是这几道防线，保证了 <code>queryLoop</code> 既能不知疲倦地连续工作，又能在完成任务或遇到异常时优雅退出。</p><h3 id="_2-流式工具执行-streamingtoolexecutor" tabindex="-1"><a class="header-anchor" href="#_2-流式工具执行-streamingtoolexecutor" aria-hidden="true">#</a> 2. 流式工具执行 (<code>StreamingToolExecutor</code>)</h3><p>以前的 AI 助手，都是等大模型把一整段话（包括工具调用的 JSON 参数）全都生成完，才去解析 JSON 并执行工具。这会导致很明显的卡顿。</p><p>但在 Claude Code 中，引入了 <code>StreamingToolExecutor</code>，实现了真正的“边看边做”：</p><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token comment">// 源码解析：工具流式执行准备</span>
<span class="token keyword">const</span> useStreamingToolExecution <span class="token operator">=</span> config<span class="token punctuation">.</span>gates<span class="token punctuation">.</span>streamingToolExecution
<span class="token keyword">let</span> streamingToolExecutor <span class="token operator">=</span> useStreamingToolExecution
  <span class="token operator">?</span> <span class="token keyword">new</span> <span class="token class-name">StreamingToolExecutor</span><span class="token punctuation">(</span>tools<span class="token punctuation">,</span> canUseTool<span class="token punctuation">,</span> toolUseContext<span class="token punctuation">)</span>
  <span class="token operator">:</span> <span class="token keyword">null</span><span class="token punctuation">;</span>

<span class="token comment">// 在接收模型流式回复时：</span>
<span class="token keyword">for</span> <span class="token keyword">await</span> <span class="token punctuation">(</span><span class="token keyword">const</span> message <span class="token keyword">of</span> deps<span class="token punctuation">.</span><span class="token function">callModel</span><span class="token punctuation">(</span><span class="token punctuation">{</span><span class="token operator">...</span><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token comment">// 1. 先把模型的回复 yield 给终端 UI 显示</span>
  <span class="token keyword">yield</span> message<span class="token punctuation">;</span>
  
  <span class="token comment">// 2. 如果大模型正在生成工具调用的参数块 (tool_use)</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span>message<span class="token punctuation">.</span>type <span class="token operator">===</span> <span class="token string">&#39;tool_use_block&#39;</span> <span class="token operator">&amp;&amp;</span> streamingToolExecutor<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// 只要拿到足够执行的参数，不等大模型说完，立刻扔进执行器！</span>
    streamingToolExecutor<span class="token punctuation">.</span><span class="token function">addTool</span><span class="token punctuation">(</span>toolBlock<span class="token punctuation">,</span> message<span class="token punctuation">)</span>
  <span class="token punctuation">}</span>
<span class="token punctuation">}</span>

<span class="token comment">// 收集执行结果</span>
<span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">const</span> result <span class="token keyword">of</span> streamingToolExecutor<span class="token punctuation">.</span><span class="token function">getCompletedResults</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  toolResults<span class="token punctuation">.</span><span class="token function">push</span><span class="token punctuation">(</span>result<span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>这就好比：</strong> 老板（大模型）一边在微信上打字给你安排任务，你（执行器）看到一半，发现需要查个资料，你就已经开始查了，等老板打完字，你的资料已经查好发回去了！这种并发设计极大地降低了任务的端到端延迟。</p><h3 id="_3-容错与重试机制-fallback" tabindex="-1"><a class="header-anchor" href="#_3-容错与重试机制-fallback" aria-hidden="true">#</a> 3. 容错与重试机制 (Fallback)</h3><p>源码中还做了非常健壮的错误处理。比如，如果你用的 Claude 3.5 Sonnet 突然因为高峰期 API 限流了，它会抛出 <code>FallbackTriggeredError</code>：</p><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token keyword">catch</span> <span class="token punctuation">(</span>innerError<span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span>innerError <span class="token keyword">instanceof</span> <span class="token class-name">FallbackTriggeredError</span> <span class="token operator">&amp;&amp;</span> fallbackModel<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// 降级触发：切换模型并重试</span>
    currentModel <span class="token operator">=</span> fallbackModel<span class="token punctuation">;</span>
    attemptWithFallback <span class="token operator">=</span> <span class="token boolean">true</span><span class="token punctuation">;</span>
    
    <span class="token comment">// 丢弃失败的工具执行</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>streamingToolExecutor<span class="token punctuation">)</span> streamingToolExecutor<span class="token punctuation">.</span><span class="token function">discard</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    
    <span class="token comment">// 给用户发个温柔的警告</span>
    <span class="token keyword">yield</span> <span class="token function">createSystemMessage</span><span class="token punctuation">(</span>
      <span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token string">Switched to </span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>fallbackModel<span class="token interpolation-punctuation punctuation">}</span></span><span class="token string"> due to high demand...</span><span class="token template-punctuation string">\`</span></span><span class="token punctuation">,</span>
      <span class="token string">&#39;warning&#39;</span>
    <span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">continue</span><span class="token punctuation">;</span> <span class="token comment">// 重新进入循环发起请求</span>
  <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="四、动手实践-给-queryengine-加个请求拦截器" tabindex="-1"><a class="header-anchor" href="#四、动手实践-给-queryengine-加个请求拦截器" aria-hidden="true">#</a> 四、动手实践：给 QueryEngine 加个请求拦截器</h2><p>光看源码不过瘾，我们来动手改一改。假设我们想在每次向大模型发请求前，强制加上一句话：“请用中文回答”。</p><p>我们可以直接在 <code>src/query.ts</code> 里的 <code>callModel</code> 调用前动手脚：</p><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token comment">// 打开 src/query.ts，在 queryLoop 函数中，找到 deps.callModel 调用的地方 (大概在 660 行左右)</span>

<span class="token comment">// 🟢 我们的实战代码：拦截并篡改系统提示词</span>
<span class="token keyword">const</span> myCustomPrompt <span class="token operator">=</span> <span class="token string">&quot;\\n\\n【重要指令】：接下来的所有回复，请必须使用中文，并且尽量使用幽默的口吻！&quot;</span><span class="token punctuation">;</span>
<span class="token keyword">const</span> hackedSystemPrompt <span class="token operator">=</span> fullSystemPrompt <span class="token operator">+</span> myCustomPrompt<span class="token punctuation">;</span>

<span class="token comment">// 然后修改 callModel 的入参</span>
<span class="token keyword">for</span> <span class="token keyword">await</span> <span class="token punctuation">(</span><span class="token keyword">const</span> message <span class="token keyword">of</span> deps<span class="token punctuation">.</span><span class="token function">callModel</span><span class="token punctuation">(</span><span class="token punctuation">{</span>
  messages<span class="token operator">:</span> <span class="token function">prependUserContext</span><span class="token punctuation">(</span>messagesForQuery<span class="token punctuation">,</span> userContext<span class="token punctuation">)</span><span class="token punctuation">,</span>
  <span class="token comment">// 替换为我们篡改后的提示词</span>
  systemPrompt<span class="token operator">:</span> hackedSystemPrompt<span class="token punctuation">,</span> 
  thinkingConfig<span class="token operator">:</span> toolUseContext<span class="token punctuation">.</span>options<span class="token punctuation">.</span>thinkingConfig<span class="token punctuation">,</span>
  tools<span class="token operator">:</span> toolUseContext<span class="token punctuation">.</span>options<span class="token punctuation">.</span>tools<span class="token punctuation">,</span>
  <span class="token comment">// ...</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token comment">// ...</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这样一改，无论你在终端输入什么，大模型都会被强制“注入”我们的中文幽默设定。这就是理解了底层架构后，我们可以随心所欲“魔改”的快乐！</p><hr><h2 id="五、小结" tabindex="-1"><a class="header-anchor" href="#五、小结" aria-hidden="true">#</a> 五、小结</h2><p>QueryEngine 是 Claude Code 最核心的引擎。它通过精细的 <strong>5 层上下文压缩</strong> 解决了长对话的内存问题，又通过 <strong>流式工具执行 (<code>StreamingToolExecutor</code>)</strong> 榨干了每一毫秒的性能，最后通过一个健壮的 <code>while(true)</code> 状态机，完成了人与大模型、本地终端之间的完美协同。</p><p>Claude Code 源码系列还未完结。敬请期待！一键三连，关注不迷路。</p><hr><h2 id="六、推荐阅读" tabindex="-1"><a class="header-anchor" href="#六、推荐阅读" aria-hidden="true">#</a> 六、推荐阅读</h2>`,53)),s("ul",null,[s("li",null,[s("a",r,[n[0]||(n[0]=a("Anthropic 官方 Tool Use 文档",-1)),t(e)]),n[1]||(n[1]=a(" —— 了解大模型是如何返回工具调用指令的。",-1))]),s("li",null,[s("a",d,[n[2]||(n[2]=a("JavaScript 异步生成器 (Async Generators)",-1)),t(e)]),n[3]||(n[3]=a(" —— 搞懂 ",-1)),n[4]||(n[4]=s("code",null,"yield",-1)),n[5]||(n[5]=a(" 和 ",-1)),n[6]||(n[6]=s("code",null,"for await...of",-1)),n[7]||(n[7]=a(" 是怎么让数据流像水管一样源源不断的。",-1))])])])}const g=o(u,[["render",k],["__file","02-query-engine.html.vue"]]);export{g as default};
